INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (7, 8, 'theory', 'Quiz: string algorithms');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 0, 'What does the prefix function value at position i store?', '["The position where the pattern first occurred", "The number of distinct letters in the substring up to position i", "The length of the longest proper prefix of the substring up to i that equals its suffix", "How many times the prefix repeats in the rest of the string"]', 2, 'For «abacaba» the values are 0, 0, 1, 0, 1, 2, 3: at the end, «aba» is both the beginning and the end of the string. These numbers tell us how far the pattern can be shifted without losing matches.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 1, 'Why does the Knuth–Morris–Pratt search run in linear time even in the worst case?', '["It sorts the text before searching", "The text pointer never goes back, and the rollbacks along the pattern table never add up to more than the steps forward", "It uses hashes and skips character checks", "It only searches for patterns no longer than five characters"]', 1, 'Each step to the right increases the match length by at most one, while rollbacks only decrease it. So there are no more rollbacks than steps to the right, which is on the order of n + m operations.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 2, 'A string of length 12 has a last prefix function value of 8. What is its smallest period?', '["8", "3", "12", "4"]', 3, 'The period is the length minus the last value: 12 − 8 = 4. Since 12 is divisible by 4, the string is one four-character piece repeated three times.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 3, 'What must you do after the hash of a text window matches the pattern hash in the Rabin–Karp algorithm?', '["Nothing: matching hashes guarantee matching strings", "Increase the hash base and recompute the window", "Skip the window: a collision means the strings are certainly different", "Compare the strings themselves character by character, because collisions are possible"]', 3, 'Equal hashes are only a candidate: different strings sometimes give the same value. A direct check is expensive only when collisions are rare, so on average the time stays linear.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (7, 8, 4, 'You need to suggest words from a typed prefix and also fix typos in queries. Which tools fit?', '["A hash table for prefixes and sorting for typos", "A trie for prefixes and the Levenshtein distance for typos", "The Levenshtein distance for prefixes and a trie for typos", "The Z-function for both tasks"]', 1, 'A trie descends along the letters of the prefix and hands over the subtree of words. The Levenshtein distance measures how many edits separate the typed word from a dictionary word. A hash table knows nothing about prefixes.');
